console.log('[forum-edit] Script loaded'); document.addEventListener('DOMContentLoaded', function () { console.log('[forum-edit] DOM ready'); const editBtns = document.querySelectorAll('.edit-post-btn'); console.log('[forum-edit] Found', editBtns.length, 'edit buttons'); document.addEventListener('click', function (e) { if (e.target.closest('.edit-post-btn')) { console.log('[forum-edit] Edit button clicked'); const btn = e.target.closest('.edit-post-btn'); const postId = btn.getAttribute('data-post-id'); const postContent = btn.getAttribute('data-post-content'); console.log('[forum-edit] postId:', postId, 'content length:', postContent ? postContent.length : 0); const modal = document.getElementById('editPostModal'); if (!modal) { console.error('[forum-edit] Modal not found'); return } console.log('[forum-edit] Modal found, setting postId'); modal.setAttribute('data-post-id', postId); const textarea = document.getElementById('editPostContent'); if (!textarea) { console.error('[forum-edit] Textarea not found'); return } console.log('[forum-edit] Textarea found, setting content'); textarea.value = postContent; console.log('[forum-edit] Showing modal'); const editModal = new bootstrap.Modal(modal); editModal.show() } }); const saveBtn = document.getElementById('saveEditPostBtn'); if (saveBtn) { console.log('[forum-edit] Save button found'); saveBtn.addEventListener('click', function () { console.log('[forum-edit] Save button clicked'); const modal = document.getElementById('editPostModal'); const postId = modal.getAttribute('data-post-id'); const content = document.getElementById('editPostContent').value; if (!content.trim()) { alert('Mensagem não pode estar vazia'); return } const formData = new FormData(); formData.append('content', content); fetch(`/post/${postId}`, { method: 'PATCH', body: formData, headers: { 'HX-Request': 'true' } }).then(r => r.text()).then(html => { const cards = document.querySelectorAll('[data-post-id="' + postId + '"]'); if (cards.length > 0) { const oldCard = cards[0].closest('.card'); if (oldCard) { const div = document.createElement('div'); div.innerHTML = html; const newCard = div.querySelector('.card'); if (newCard) { oldCard.parentNode.replaceChild(newCard, oldCard) } } } const editModal = bootstrap.Modal.getInstance(document.getElementById('editPostModal')); if (editModal) editModal.hide() }).catch(err => console.error('[forum-edit] Error:', err)) }) } else { console.error('[forum-edit] Save button not found') } }); 
